function onInit(self, engine) {
  if (typeof self.started !== 'boolean') self.started = false;
  if (typeof self.completed !== 'boolean') self.completed = false;
  var manager = engine.uiManager || (typeof KozUIManager !== 'undefined' ? KozUIManager : null) || (typeof uiManager !== 'undefined' ? uiManager : null);
  if (!manager) return;
  manager.registerScreen(self.id + '_menu', {
    layer: 'hud',
    layerOrder: 100,
    isVisible: function() { return !self.started; },
    create: function() {
      var wrap = document.createElement('div');
      wrap.style.cssText = 'position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:linear-gradient(180deg, rgba(15,23,42,0.88), rgba(2,6,23,0.94));pointer-events:auto;font-family:Trebuchet MS,sans-serif;';
      var card = document.createElement('div');
      card.style.cssText = 'width:min(520px,92vw);padding:28px 26px;border-radius:18px;background:rgba(15,23,42,0.96);border:1px solid rgba(148,163,184,0.25);box-shadow:0 24px 80px rgba(0,0,0,0.45);color:#e2e8f0;';
      var title = document.createElement('h1');
      title.textContent = props.title || 'Koz Template';
      title.style.cssText = 'margin:0 0 8px;font-size:34px;';
      var subtitle = document.createElement('p');
      subtitle.textContent = props.subtitle || '';
      subtitle.style.cssText = 'margin:0 0 14px;color:#94a3b8;line-height:1.4;';
      var instructions = document.createElement('p');
      instructions.textContent = props.instructions || '';
      instructions.style.cssText = 'margin:0 0 18px;color:#cbd5e1;line-height:1.5;';
      var button = document.createElement('button');
      button.textContent = props.actionLabel || 'Start';
      button.style.cssText = 'padding:12px 18px;border:none;border-radius:999px;background:#22c55e;color:#052e16;font-weight:700;cursor:pointer;';
      button.onclick = function() {
        self.started = true;
        self.completed = false;
        if (typeof self.onStartGame === 'function') self.onStartGame();
      };
      var note = document.createElement('p');
      note.textContent = props.note || '';
      note.style.cssText = 'margin:14px 0 0;color:#64748b;font-size:12px;line-height:1.5;';
      card.appendChild(title);
      if (subtitle.textContent) card.appendChild(subtitle);
      if (instructions.textContent) card.appendChild(instructions);
      card.appendChild(button);
      if (note.textContent) card.appendChild(note);
      wrap.appendChild(card);
      return wrap;
    }
  });
}

function onUpdate(self, engine, dt) {}

function onInit(self, engine) {
  var manager = engine.uiManager || (typeof KozUIManager !== 'undefined' ? KozUIManager : null) || (typeof uiManager !== 'undefined' ? uiManager : null);
  self.onStartGame = function() {
    var player = engine.findObject('obj_player');
    if (!player) return;
    player.x = player.spawnX || 48;
    player.y = player.spawnY || 120;
    player.vx = 0;
    player.vy = 0;
    player.grounded = false;
  };
  if (!manager) return;
  manager.registerScreen(self.id + '_hud', {
    layer: 'hud',
    layerOrder: 10,
    isVisible: function() { return !!self.started; },
    create: function() {
      var panel = document.createElement('div');
      panel.style.cssText = 'position:absolute;left:16px;top:16px;padding:10px 12px;border-radius:12px;background:rgba(15,23,42,0.76);color:#e2e8f0;font-family:Trebuchet MS,sans-serif;pointer-events:none;';
      panel.innerHTML = '<div id="platformerStatus" style="font-size:14px;font-weight:700;"></div><div style="margin-top:4px;font-size:12px;color:#94a3b8;">Reach the green goal block.</div>';
      return panel;
    },
    update: function() {
      var status = document.getElementById('platformerStatus');
      var player = engine.findObject('obj_player');
      if (!status) return;
      if (self.completed) status.textContent = 'Goal reached. Press Start to run it again.';
      else status.textContent = 'Player ' + Math.round(player ? player.x : 0) + ', ' + Math.round(player ? player.y : 0);
    }
  });
}

function onUpdate(self, engine, dt) {}

function onInit(self, engine) {
  self.vx = 0;
  self.vy = 0;
  self.grounded = false;
  self.spawnX = self.x;
  self.spawnY = self.y;
}

function overlaps(a, b) {
  return !!(a && b && a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y);
}

function onUpdate(self, engine, dt) {
  var game = engine.findObject('obj_game_state');
  if (!game || !game.started || game.completed) return;
  var left = keyIsDown(65) || keyIsDown(LEFT_ARROW);
  var right = keyIsDown(68) || keyIsDown(RIGHT_ARROW);
  var jump = keyIsDown(SPACE) || keyIsDown(87) || keyIsDown(UP_ARROW);

  self.vx = 0;
  if (left && !right) self.vx = -160;
  if (right && !left) self.vx = 160;
  if (self.grounded && jump && !self.jumpLatch) {
    self.vy = -340;
    self.jumpLatch = true;
  }
  if (!jump) self.jumpLatch = false;

  self.vy += 880 * dt;
  self.x += self.vx * dt;
  self.y += self.vy * dt;

  if (self.y > 340) {
    self.x = self.spawnX;
    self.y = self.spawnY;
    self.vx = 0;
    self.vy = 0;
  }

  var goal = engine.findObject('obj_goal');
  if (overlaps(self, goal)) {
    game.completed = true;
    game.started = false;
  }
}
